import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.C0B4Gdhp.js";const b=JSON.parse('{"title":"Web で開く","description":"","frontmatter":{},"headers":[],"relativePath":"guide/web.md","filePath":"guide/web.md","lastUpdated":1789914287000}'),o={name:"guide/web.md"};function d(n,e,p,c,h,l){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="web-で開く" tabindex="-1">Web で開く <a class="header-anchor" href="#web-で開く" aria-label="Permalink to &quot;Web で開く&quot;">​</a></h1><p>Web は部分対応です。Unity 6000.6.2f1、パッケージ 8.0.0-pre.1 です。実機センサーの課題の代用にはなりません。</p><h2 id="ビルドと開き方" tabindex="-1">ビルドと開き方 <a class="header-anchor" href="#ビルドと開き方" aria-label="Permalink to &quot;ビルドと開き方&quot;">​</a></h2><p>通常のアプリは、ビルド設定で Web を選び、<code>Assets/Game.unity</code> をビルドします。出力先は、ビルドのときに指定したフォルダです。診断アプリは <code>bash scripts/unity-validate.sh web</code> です。出力は <code>Build/Validation/Web</code> です。</p><p>ビルドしたフォルダは HTTP サーバで開きます。ローカルのプレビュー例です。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Build/Validation/Web</span></span></code></pre></div><p>このコマンドは、その PC を使う本人だけが開くためのものです。外部公開は別です。ブラウザで <code>http://127.0.0.1:8000</code> を開きます。</p><p>カメラなど権限付き機能には、HTTPS か localhost の安全なコンテキストが要ります。通信は接続先の CORS 許可も要ります。無いと取れません。</p><h2 id="テンプレート" tabindex="-1">テンプレート <a class="header-anchor" href="#テンプレート" aria-label="Permalink to &quot;テンプレート&quot;">​</a></h2><p>標準テンプレートは <code>Assets/WebGLTemplates/GameCanvas/index.html</code> です。画面サイズに合わせ、<code>autoSyncPersistentDataPath</code> は真です。既定の Player Settings の WebGL テンプレートは <code>PROJECT:GameCanvas</code> です。</p><h2 id="実装と確認" tabindex="-1">実装と確認 <a class="header-anchor" href="#実装と確認" aria-label="Permalink to &quot;実装と確認&quot;">​</a></h2><p>実装があることと、確認した範囲は別です。カメラの入口は Web にもあります。位置情報と加速度は Web では未対応で、<code>Start</code> すると <code>Unsupported</code> です。</p><p>確認した環境は localhost 上の Codex 内蔵ブラウザ Chromium 153 です。画像と日本語、マウスの <code>gc.Drag</code>、Space の Down と Up、HTTP GET の本文と画像、404、Cancel、Timeout、保存と再読み込みを確認しました。画面をクリックしたあと、診断アプリは gc.IsPlayingSound(GcSoundTrack.SE) の戻り値が真であることをログに出しました。耳では再生を確認していません。カメラは許可待ちから <code>NotGranted</code> へ完了し、<code>Stop</code> で <code>Stopped</code> までを確認しました。実映像は未確認です。</p><p>Chrome や Safari の本体、スマホのブラウザ、タッチ、複数指、背景からの復帰は未確認です。内蔵ブラウザでの成功を、通常のブラウザの保証にはしません。</p>',14)])])}const k=a(o,[["render",d]]);export{b as __pageData,k as default};
